import type { Technique } from '../solver/addsub';

/** Paragraph text; `**bold**` is the only markup. */
export interface TextBlock {
  type: 'text';
  paragraphs: string[];
}

/** A small live task: set `value` on the frame. */
export interface TryBlock {
  type: 'try';
  prompt: string;
  value: number;
  rods?: number;
}

/** An animated walkthrough generated by the solver. */
export interface DemoBlock {
  type: 'demo';
  title: string;
  terms: number[];
  rods?: number;
}

export type LessonBlock = TextBlock | TryBlock | DemoBlock;

export type PracticeKind =
  | { kind: 'set'; digits: [number, number]; showValues: boolean }
  | { kind: 'read'; digits: [number, number] }
  | {
      kind: 'addsub';
      digits: [number, number];
      terms: number;
      subtractChance: number;
      allowed: Technique[];
      require?: Technique[];
    };

export interface PracticeSet {
  id: string;
  title: string;
  problems: number;
  rods?: number;
  spec: PracticeKind;
}

export interface Level {
  id: string;
  number: number;
  title: string;
  summary: string;
  learn: LessonBlock[];
  practice: PracticeSet[];
}
